App.register({group:'delivery',label:'08 / 审核与交付',routes:[{path:'delivery/review',title:'成片终审',icon:'◉',permission:'delivery',render(){if(DB.state.tenant!=='tn-north'||DB.state.identity==='employee')return UI.page('HUMAN GATE / FINAL CUT','当前租户暂无待终审作品','终审队列只展示当前租户及当前身份获授权的项目。','',`<div class="card">${UI.empty('暂无待终审作品','当前租户没有分配给你的最终审核任务。')}</div>`);return UI.page('HUMAN GATE / FINAL CUT','最终成片审核','人工审核节点 B：确认整剧内容、画面、音频、字幕、集数完整性与交付质量。',UI.btn('进入交付中心','go:delivery/center','btn'),`<div class="notice warn">AI 质检通过不等于正式交付。必须由员工完成最终成片审核，才能进入交付归档。</div><div class="grid grid-3 section-gap">${UI.metric('待终审作品','01','她的第七码头','◉')}${UI.metric('AI 质检综合分','96 / 100','全部集数已完成检测','✓')}${UI.metric('待确认项','1','第 11 集字幕断句','!')}</div><div class="grid grid-2 section-gap"><div class="card card-dark"><div class="eyebrow" style="color:var(--lime)">FINAL CUT / PREVIEW</div><div style="height:210px;background:linear-gradient(135deg,#344b55,#141e27);border-radius:10px;display:grid;place-items:center;margin:12px 0"><div style="text-align:center"><div style="font-size:34px">▶</div><div class="tiny" style="color:#bdc8ca">演示预览画面 · 不包含真实视频流</div></div></div><div class="small">《她的第七码头》 · 全 16 集 · V1.0 候选交付版</div></div><div class="card"><div class="card-title">最终审核清单</div>${['剧情完整与故事闭环','人物形象及跨集一致性','视频画面与镜头衔接','配音、配乐与音效质量','字幕准确性与时间轴','集数完整及交付文件齐全','内容合规与版权授权'].map((x,i)=>`<label class="kpi-line"><span>${x}</span><input type="checkbox" ${i===5?'checked':''}></label>`).join('')}<div class="field-wrap section-gap"><span class="field-label">审核意见</span><textarea class="field" placeholder="记录最终审核结论或指定返修范围"></textarea></div><div class="section-gap">${UI.btn(DB.state.finalApproved?'审核已通过':'审核通过','final:approve','btn-lime')}</div></div></div>`); }},{path:'delivery/center',title:'作品交付中心',icon:'⇧',permission:'delivery',render(){if(DB.state.tenant!=='tn-north'||DB.state.identity==='employee')return UI.page('DELIVERY / RELEASE','当前租户暂无交付任务','交付队列只展示当前租户及当前身份获授权的项目。','',`<div class="card">${UI.empty('暂无待交付作品','当前租户没有分配给你的交付任务。')}</div>`);return UI.page('DELIVERY / RELEASE','作品交付与归档','管理正式成片、分集文件、字幕、封面、交付清单和版本追溯。',UI.btn('查看终审','go:delivery/review','btn'),`<div class="grid grid-3">${UI.metric('待交付作品','1','等待人工终审放行','⇧')}${UI.metric('本月正式交付','6','仅统计已归档作品','✓')}${UI.metric('归档资产','32','成片及交付附件','▧')}</div><div class="card section-gap"><div class="card-head"><div><div class="card-title">交付单 · 她的第七码头</div><div class="card-sub mono">DL-26038 / SP-26038 / 16 Episodes</div></div>${UI.tag(DB.state.delivered?'已归档':DB.state.finalApproved?'待生成交付包':'待终审',DB.state.delivered?'green':'orange')}</div><div class="grid grid-2"><div><div class="kpi-line"><span>成片文件</span><b>16 / 16 集</b></div><div class="kpi-line"><span>字幕文件</span><b>16 / 16 集</b></div><div class="kpi-line"><span>封面与海报</span><b>2 项</b></div><div class="kpi-line"><span>交付清单</span><b>完整性检查通过</b></div></div><div><div class="notice success">交付包内容已完成完整性检查。最终审核通过后，才允许生成正式交付记录与归档版本。</div><div class="section-gap">${UI.btn(DB.state.delivered?'已完成正式归档': '生成交付包并归档','delivery:publish','btn-lime')}</div><div class="tiny muted section-gap">演示交互：仅更新内存状态，不生成真实媒体文件。</div></div></div></div>`);}}]});
